def get_course_run_key(module):
    """
    Safely extract the course run key from a module description.

    Parameters
    ----------
    module : dict | None
        Expected to be a dictionary with the following (nested) structure::

            {
                "scope_ids": {
                    "usage_id": {
                        "course_key": "<course run key as string>"
                    }
                }
            }

        If `module` is None or the structure is not respected, the
        function returns None.

    Returns
    -------
    str | None
        The stringified course run key if it can be found, otherwise None.
    """
    # The module must be a dictionary to possibly contain the keys.
    if not isinstance(module, dict):
        return None

    try:
        course_key = module["scope_ids"]["usage_id"]["course_key"]
    except (KeyError, TypeError):
        # KeyError: one of the expected keys is missing.
        # TypeError: an intermediate value is not a dict (e.g., None).
        return None

    # If it isn't already a string, stringify it; otherwise return as-is.
    return str(course_key) if course_key is not None else None

def get_closest_prime(n: int) -> int:
    """
    Return `n` itself if it is prime; otherwise return the prime number
    closest to `n`.  If two primes are equidistant, return the smaller one.
    """

    def is_prime(num: int) -> bool:
        """Simple deterministic primality test."""
        if num < 2:
            return False
        if num in (2, 3):
            return True
        if num % 2 == 0 or num % 3 == 0:
            return False

        i, step = 5, 2          # wheel with 6k ± 1 optimization
        while i * i <= num:
            if num % i == 0:
                return False
            i += step
            step = 6 - step      # alternates between +2 and +4 (i.e., 6k±1)
        return True

    # If n itself is prime, return it right away.
    if is_prime(n):
        return n

    # For all n < 2 the closest (and first) prime is 2.
    if n < 2:
        return 2

    # Expand outward from n until a prime is found.
    distance = 1
    while True:
        lower = n - distance
        upper = n + distance

        lower_is_prime = is_prime(lower) if lower >= 2 else False
        upper_is_prime = is_prime(upper)

        # Preference order enforces "smaller if tied".
        if lower_is_prime and upper_is_prime:
            return lower
        if lower_is_prime:
            return lower
        if upper_is_prime:
            return upper

        distance += 1

