from typing import Dict, Any

def process_user_credentials(credentials: Dict[str, str]) -> Dict[str, Any]:
    """
    Processes a dictionary containing user credentials and returns a new
    dictionary with a 'title' and 'data' fields.

    Args:
        credentials (Dict[str, str]): A dictionary expected to contain the keys
            'username' and 'password'.

    Returns:
        Dict[str, Any]: 
            - An empty dictionary if either 'username' or 'password' is missing.
            - Otherwise, a dictionary with:
                {
                    'title': <username>,
                    'data': {
                        'username': <username>,
                        'password': <password>
                    }
                }
    """
    # Validate presence of required keys
    if not isinstance(credentials, dict):
        return {}

    username = credentials.get("username")
    password = credentials.get("password")

    if username is None or password is None:
        return {}

    # Build the desired output structure
    processed = {
        "title": username,
        "data": {
            "username": username,
            "password": password
        }
    }
    return processed

