from functools import wraps

def use_context(func):
    """
    Decorator that guarantees a context dictionary is created once
    and made available to the wrapped function on every call.
    The context always contains {'status': 'active'}.
    """
    # Initialise the required context a single time.
    context = {'status': 'active'}

    @wraps(func)
    def wrapper(*args, **kwargs):
        # Inject the context for the wrapped function.
        # (Caller-provided context, if any, is left untouched.)
        kwargs.setdefault('context', context)
        return func(*args, **kwargs)

    return wrapper


@use_context
def my_function(context):
    """
    Returns the current status held in the shared context.
    """
    return context['status']
